import json,html,shutil,argparse,hashlib,math
ROOT=Path(__file__).resolve().parents[1]
E=html.escape
NAMES={'veil':('透幕','VEIL','直立均衡，让孔场与周边留白保持相近的份量。'),'horizon':('横幕','HORIZON','降低高度、横向展开，曲面也变得更平。'),'fold':('曲幕','FOLD','收窄、抬高并加深弯曲，让不同方向的遮挡更明显。')}
def compose(dest,draft=True):
 def img(key,view,alt,lazy=False):return f'<img src="assets/{key}/{view}.png" alt="{E(alt)}" width="{1584 if view=="beauty-wide" else 960}" height="960"'+(' loading="lazy"' if lazy else '')+'>'
 def placeholder(text):return f'<div class="placeholder"><strong>{text}</strong><small>待接入真实模型图版 · 不作几何证据</small></div>'
 def asset(key,view,alt):return placeholder('图版接入中') if draft else img(key,view,alt,True)
