 strip=placeholder('008') if draft else img('veil','hole-detail','透幕孔缘CPU近景的竖幅裁片；裁切只用于观察材质和实体边缘')
 if draft:inputs={'height':'待真实配置','width':'待真实配置','thickness':'待真实配置','hole_count':'待几何报告'}
 else:
  infos={k:json.loads((dest/'assets'/k/'model-info.json').read_text()) for k in NAMES}
  manifest=json.loads((dest/'manifest.json').read_text());native={};native_paths={}
  for k in NAMES:
   ip=dest/manifest['final_identity_reports'][k];identity=json.loads(ip.read_text());np=ip.parent/identity['checks']['native']['report'];native[k]=json.loads(np.read_text());native_paths[k]=np
  info=infos['veil'];cfg=info['config'];con=info['construction'];inputs={'height':f'{cfg["height"]*1000:.0f} mm','width':f'{cfg["width"]*1000:.0f} mm','thickness':f'{cfg["thickness"]*1000:.1f} mm','hole_count':str(con['hole_count'])}
 cards=''
 for num,(k,(cn,en,desc)) in enumerate(NAMES.items(),1):
  if draft:stats='<div><dt>名义比例 / 曲率 / 开孔</dt><dd>待真实配置</dd></div>'
  else:
   i=infos[k];c=i['config'];d=i['dimensions_mm'];g=i['construction'];lig=min(x['conservative_polyline_lower_bound_m'] for x in native[k]['ligament_sampling']['records'])
   stats=f'<div><dt>名义展开宽 × 高</dt><dd>{c["width"]*1000:.0f} × {c["height"]*1000:.0f} mm</dd></div><div><dt>名义圆心角</dt><dd>{c["curve_angle_degrees"]:.0f}°</dd></div><div><dt>真实包围盒 宽 × 深 × 高</dt><dd>{d["width"]:.1f} × {d["depth"]:.1f} × {d["height"]:.1f} mm</dd></div><div><dt>解析孔口面积比²</dt><dd>{g["surface_open_area_ratio"]*100:.1f}%</dd></div><div><dt>孔口/外缘净空下界¹</dt><dd>≥ {math.floor(lig*100000)/100:.2f} mm</dd></div>'
  cards+=f'<article><div class="variant-title"><h3>{cn}</h3><span>0{num} / {en}</span></div><figure class="variant-plate">{asset(k,"beauty",cn+"真实模型整体斜视CPU图")}</figure><p class="variant-copy">{desc}</p><dl class="stats">{stats}</dl>'+('<p class="text-small">候选尚未冻结</p>' if draft else f'<a class="variant-action" href="viewer/index.html?variant={k}">独立观察 {cn} ↗</a>')+'</article>'
 downloads='<p class="pending">当前只审网页排版。真实资产未冻结，下载暂不开放。</p>' if draft else '<ul class="download-list">'+''.join(f'<li><span>{cn} / {en}</span><span><a download href="assets/{k}/model.glb">GLB</a> · <a data-download="{k}-native" download href="assets/{k}/model.blend">Blender</a> · <a download href="assets/{k}/config.json">配置</a></span></li>' for k,(cn,en,_) in NAMES.items())+'</ul><p><a href="manifest.json">原模型清单</a> · <a href="model-source.html">源码与报告</a> · <a href="web-review/asset-parity.json">接入字节核对</a></p>'
 static='' if draft else '<div class="static-images">'+''.join(f'<figure>{img("veil",v,a,True)}<figcaption>{t} / CPU渲染</figcaption></figure>' for v,t,a in [('beauty','整体斜视','透幕完整厚壳的真实整体斜视CPU渲染'),('hole-detail','孔缘局部','透幕孔缘局部CPU图，显示前后边缘与厚度'),('top','俯看遮挡','透幕从上方向下的正交视图')])+'</div>'
 page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>透幕 VEIL · 看见孔，也看见连料 / 008</title><meta name="description" content="原创穿孔厚壳透幕的观察图版。分别阅读孔洞、视角遮挡与孔间连料；附真实模型、参数与证据。"><link rel="stylesheet" href="style.css">{'' if draft else '<script src="plate-state.js" defer></script><script src="app.js" defer></script>'}</head><body><a class="skip" href="#main">跳至正文</a><div class="wrap"><header class="mast"><strong>{"造物手记 / FIELD NOTES" if draft else '<a href="../../index.html">造物手记 / FIELD NOTES</a>'}</strong><div class="edition">008 · 透幕 VEIL <span>/ 穿孔厚壳研究</span></div></header></div><main id="main"><div class="wrap"><section class="intro"><div><p class="kicker">A field of apertures / 008</p><h1><span>Veil.</span>让视线<br>有处穿过。</h1></div><div class="intro-right"><p>孔，是留出的空处。<br>幕，是那些没有被挖去的部分。</p><p class="text-small">用一片连续的弯曲厚壳，观察孔洞、遮挡与孔间连料。<br>{'网页排版首版 · 明确占位 · 不可作为模型交付' if draft else '原创数字小屏风 / CPU图版 / 不是光学或结构性能测试'}</p></div></section><section aria-label="透幕观察图版"><div class="observation"><figure class="main-plate" aria-labelledby="current-caption"><span class="plate-tag">PLATE 01 / <span data-image-tag>VEIL</span></span><div data-image-frame>{hero}</div><p class="image-fallback" hidden data-fallback>图版暂不可用。下方正文、参数与下载仍可阅读。</p></figure><figure class="strip-plate">{strip}<span class="vertical">EDGE STUDY / 孔缘竖幅裁片</span></figure><aside class="rules" aria-label="当前图版参数"><div class="rule-head"><span class="label">Current specimen</span><strong data-title>透幕 / VEIL</strong><span class="text-small" data-identity>连续穿孔厚壳</span></div><dl><div><dt>名义展开宽</dt><dd data-stat="width">{inputs['width']}</dd></div><div><dt>名义高度</dt><dd data-stat="height">{inputs['height']}</dd></div><div><dt>名义壳厚</dt><dd data-stat="thickness">{inputs['thickness']}</dd></div><div><dt>几何孔数</dt><dd data-stat="hole_count">{inputs['hole_count']}</dd></div></dl><p class="rule-note">输入尺寸与测量值分层记账。<br>壳厚不等于孔口之间的净空。</p></aside></div><div class="below-plate"><div><div class="figline"><span id="current-caption" data-caption>{'明确占位 / 尚未接入真实模型' if draft else '透幕 · 整体斜视 / Cycles CPU'}</span>{'' if draft else '<span><a data-original href="assets/veil/beauty-wide.png">完整原图 ↗</a> · <a data-crop-original href="assets/veil/hole-detail.png">孔缘原图 ↗</a></span>'}</div><div class="controls" data-controls {'' if draft else 'hidden'}><div class="control-group" aria-label="选择几何预设">{''.join(f'<button type="button" data-variant="{k}" aria-pressed="{str(k=="veil").lower()}" {"disabled" if draft else ""}>{cn}</button>' for k,(cn,en,_) in NAMES.items())}</div><div class="control-group" aria-label="选择图版">{''.join(f'<button type="button" data-view="{v}" aria-pressed="{str(v=="beauty").lower()}" {"disabled" if draft else ""}>{cn}</button>' for v,cn in [('beauty','整体'),('hole-detail','孔缘'),('top','俯看')])}<button type="button" data-retry class="retry" hidden>重试图版</button></div></div><p class="status" aria-live="polite" aria-atomic="true" data-status>{'控件为排版预览，真实图版接入后启用。' if draft else ''}</p></div>{'<span class="pending">独立三维观察页待模型冻结</span>' if draft else '<a class="view-link" data-viewer href="viewer/index.html?variant=veil">进入独立三维观察 <span>↗</span></a>'}</div></section><nav class="chapter-nav" aria-label="观察章节"><a href="#reading">01 / 三种读法 <span>READ</span></a><a href="#family">02 / 三片不同的幕 <span>COMPARE</span></a><a href="#archive">03 / 制作档案 <span>TRACE</span></a></nav><section id="reading" class="section"><div class="section-head"><span class="label">01 / Reading the surface</span><div><h2>不要只看穿过去的地方。</h2><p>同一片曲面，可以先读孔的轮廓，再读偏转视角后的遮挡，最后沿孔与孔之间剩下的实体行走。三个问题互相关联，但不能由同一个“开孔率”回答。</p></div></div><div class="reading-grid"><article><figure>{asset('veil','front','透幕真实正面正交CPU图，用于阅读孔阵列')}</figure><span class="number">01 / APERTURE</span><h3>孔洞</h3><p>孔有前缘、后缘和孔壁。它们不是平面上的深色贴图，而是穿过厚壳的几何通道。</p><p class="image-credit">真实正面正交图 / 不等于透光率</p></article><article><figure>{asset('veil','top','透幕真实俯视正交CPU图，显示弯曲与实体遮挡')}</figure><span class="number">02 / OCCLUSION</span><h3>遮挡</h3><p>角度一变，前后孔缘会重叠。图里看不见的空白，不意味着模型里没有孔。</p><p class="image-credit">真实俯视正交图 / 不作光学模拟</p></article><article><figure>{asset('veil','hole-detail','透幕真实孔缘局部CPU图，显示孔间剩余实体')}</figure><span class="number">03 / LIGAMENT</span><h3>连料</h3><p>连续的实体把孔场连接成一片幕。孔口净空与壳体厚度是两种量，不应混用。</p><p class="image-credit">真实孔缘局部图 / 不作强度验收</p></article></div>{static}<noscript><p class="text-small">JavaScript未启用：上方真实静态图版与下方三预设、参数、源码和下载仍可独立阅读。</p></noscript></section></div><section class="band" id="family"><div class="wrap section"><div class="section-head"><span class="label">02 / Same rule, different field</span><div><h2>三片不同的幕，<br>不是三种颜色。</h2><p>改变展开比例、曲率与真实开孔。材质语言保持一致，让差别留在形体上。</p></div></div><div class="matrix">{cards}</div><p class="definitions">名义展开宽是曲面展开后的输入尺寸，不等于模型包围盒宽；圆心角是名义曲率控制。¹下界来自实际前/后孔口折线之间、孔口到同侧外缘的3D欧氏净空取样，扣除两端覆盖半径及数值余量，展示时向下保留两位毫米小数；不代表孔内壁全域最薄或测地距离，更不构成可制造、抗冲击或安全的保证。²解析孔口面积比＝光滑孔口足迹面积/中面展开矩形面积；不是三角网格实测面积、投影可见率、孔隙率或透光率。{'当前图版与测值等待正式模型，尚不可比较。' if draft else ''}</p></div></section><div class="wrap"><section class="section" id="archive"><div class="section-head"><span class="label">03 / Trace the making</span><div><h2>图版之外，留下证据。</h2><p>模型、参数、生成源和网页评审分别保留。漂亮的孔场不是门禁；一次“通过”也不覆盖所有层级。</p></div></div><div class="archive"><div><h3>模型与可复跑来源</h3>{downloads}<p>数字研究，不提供物理自立、制造、公差、强度或光学性能的承诺。连续参数域未由三个预设证明。</p></div><div><h3>网页的改动记录</h3>{'<p>先完成这一版可审原型，再访问原作者／机构的真实网页作后评审。研究、采用与不采用以及修改证据会单列。</p>' if draft else '<div class="report-links"><a href="web-review/reference-notes.html">实际外部后评审 ↗</a><a href="web-review/design-review.html">设计修订 ↗</a><a href="web-review/reflection.html">复盘与前后 ↗</a></div>'}<details><summary>通过、未验与不适用，分开说</summary><p>正文与原生章节锚点不依赖脚本。{'本首版尚未做浏览器验收。' if draft else '实际浏览器检查见<a href="web-review/browser-qa.html">验收记录</a>。'}GPU、实体iPhone、200%缩放与完整读屏未实际验证时，不由CPU图、CSS窄屏或单元测试替代。</p></details></div></div></section></div></main><div class="wrap"><footer class="footer"><span>造物手记 / 008 · 透幕 VEIL</span><span>{'网页排版首版 · 模型未接入 · 未发布' if draft else '独立观察页面 / 原创数字形体 / <a href="../../methods/quality-workflow-v2/index.html">工作法 v2</a>'}</span></footer></div></body></html>'''
 dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(page)
 if (ROOT/'style.css').resolve()!=(dest/'style.css').resolve():shutil.copy2(ROOT/'style.css',dest/'style.css')
 if not draft:
  for name in ['app.js','plate-state.js']:
   if (ROOT/name).resolve()!=(dest/name).resolve():shutil.copy2(ROOT/name,dest/name)
  def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
  data={'study':'008','scope':'Web display summaries derived from original frozen model files. Nominal inputs are not geometric measurements.','variants':{}}
  for k,(cn,en,desc) in NAMES.items():
   c=infos[k]['config'];g=infos[k]['construction']
   data['variants'][k]={'title':cn+' / '+en,'stats':{'width':f'{c["width"]*1000:.0f} mm','height':f'{c["height"]*1000:.0f} mm','thickness':f'{c["thickness"]*1000:.1f} mm','hole_count':str(g['hole_count'])},'images':{v:f'assets/{k}/{"beauty-wide" if v=="beauty" else v}.png' for v in ('beauty','hole-detail','top')},'source_info_sha256':sha(dest/'assets'/k/'model-info.json'),'source_glb_sha256':sha(dest/'assets'/k/'model.glb'),'identity_report':manifest['final_identity_reports'][k],'source_native_report':native_paths[k].relative_to(dest).as_posix(),'source_native_report_sha256':sha(native_paths[k]),'comparison':{'bbox_mm':infos[k]['dimensions_mm'],'nominal_curve_angle_degrees':c['curve_angle_degrees'],'analytic_footprint_ratio':g['surface_open_area_ratio'],'mouth_polyline_lower_bound_m':min(x['conservative_polyline_lower_bound_m'] for x in native[k]['ligament_sampling']['records']),'lower_bound_display_mm':math.floor(min(x['conservative_polyline_lower_bound_m'] for x in native[k]['ligament_sampling']['records'])*100000)/100}}
  (dest/'web-assets').mkdir(exist_ok=True);(dest/'web-assets/plate-data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
  delivery={'study':'008','scope':'Download-only URL and label projection. It must not rewrite geometry metadata or app code.','downloads':{k+'-native':{'href':f'assets/{k}/model.blend','label':'Blender'} for k in NAMES}}
  (dest/'web-delivery.json').write_text(json.dumps(delivery,ensure_ascii=False,indent=2)+'\n')
  parity=json.loads((dest/'web-review/asset-parity.json').read_text())
  sections=[]
  for prefix,title in [('source/','生成源码与检查器'),('configs/','参数预设'),('review/','原模型评审与检查报告')]:
   rows=[q for q in parity['files'] if q['path'].startswith(prefix)]
   sections.append('<details><summary>'+title+' / '+str(len(rows))+'个文件</summary><ul>'+''.join('<li><a href="'+E(q['path'])+'">'+E(q['path'])+'</a> <small>'+f"{q['bytes']:,}"+' bytes</small></li>' for q in rows)+'</ul></details>')
  extra_roots=[q for q in parity['files'] if '/' not in q['path']]
  roots='<ul>'+''.join('<li><a href="'+E(q['path'])+'">'+E(q['path'])+'</a></li>' for q in extra_roots)+'</ul>'
  (dest/'model-source.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>008 原模型源码与报告</title><link rel="stylesheet" href="style.css"></head><body class="report-page"><a href="index.html#archive">← 返回制作档案</a><main><h1>原模型源码与报告</h1><p>这些是经批准原包里的真实文件，不是网页另写的一份模型结论。按README的环境和命令复跑；保留脚本依赖及相应配置。失败历史与正式资产分别阅读，不把早期报告当最终身份。</p>'+roots+''.join(sections)+'<h2>网页自己的证据</h2><p><a href="web-review/asset-parity.json">逐文件接入SHA256</a> · <a href="web-review/browser-qa.html">有限浏览器验收</a> · <a href="WEB-README.html">网页说明与复跑命令</a></p></main></body></html>')

